8. use crate::mm::phys::{
9.     frame,
10.     upool::UserFrame,
11. };
12. 
13. //==================================================================================================
14. // Constants
15. //==================================================================================================
16. 
17. /// Total number of physical frames derived from `MEMORY_SIZE` and `FRAME_SIZE`.
18. const TOTAL_FRAMES: usize = config::kernel::MEMORY_SIZE / ::arch::mem::FRAME_SIZE;
19. 
20. /// Number of frames allocated per round. Matches the number of frames initially mapped for a
21. /// user-level stack at process creation (`USER_STACK_MIN_SIZE / FRAME_SIZE`), so each round
22. /// exercises the eager stack allocation pattern without depending on demand-paged growth.
23. const FRAMES_PER_ROUND: usize =
24.     ::config::memory_layout::USER_STACK_MIN_SIZE / ::arch::mem::FRAME_SIZE;
25. 
26. /// Number of alloc/free rounds. Each round allocates `FRAMES_PER_ROUND` frames and then drops them.
27. /// If any frames leak, later rounds will exhaust the frame allocator. Set to twice the number of
28. /// rounds needed to fill the pool so that even a single leaked frame per round causes exhaustion
29. /// before the test ends.
30. const ROUNDS: usize = TOTAL_FRAMES / FRAMES_PER_ROUND * 2;
31. 
32. /// Static backing store for one round's worth of [`UserFrame`]s. Avoids heap allocation so the
33. /// test cannot exhaust the kernel heap regardless of `FRAMES_PER_ROUND`.
34. ///
35. /// # Safety
36. ///
37. /// Accessed only from the single-threaded kernel test path; no concurrent access is possible.
38. static mut FRAMES: [Option<UserFrame>; FRAMES_PER_ROUND] = [const { None }; FRAMES_PER_ROUND];
39. 
40. //==================================================================================================
41. // Tests
42. //==================================================================================================
43. 
44. ///
45. /// # Description
46. ///
47. /// Allocates a batch of [`UserFrame`]s and drops them, verifying that `Drop` returns every frame
48. /// to the allocator. Repeats for several rounds so that even a single leaked frame per round
49. /// eventually exhausts the pool and causes an allocation failure.
50. ///
51. fn test_user_frame_drop_reclaims_frames() -> bool {
52.     for round in 0..ROUNDS {
53.         // SAFETY: single-threaded kernel; no concurrent access to `FRAMES`.
54.         let frames: &mut [Option<UserFrame>; FRAMES_PER_ROUND] =
55.             unsafe { &mut *core::ptr::addr_of_mut!(FRAMES) };
56. 
57.         for slot in frames.iter_mut() {
58.             match frame::alloc() {
59.                 Ok(addr) => *slot = Some(UserFrame::new(addr)),
60.                 Err(e) => {
61.                     error!("frame allocation failed at round {round} (error={e:?}), possible leak");
62.                     // Clear any slots populated in this round so their `UserFrame`s are dropped
63.                     // before returning on the error path.
64.                     for slot in frames.iter_mut() {
65.                         *slot = None;
66.                     }
67.                     return false;
68.                 },
69.             }
70.         }
